PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE PROJECT_META(KEY TEXT PRIMARY KEY,VALUE TEXT);
INSERT INTO PROJECT_META VALUES('pt_separator','-');
CREATE TABLE PT(ID INTEGER PRIMARY KEY AUTOINCREMENT,NAME TEXT NOT NULL UNIQUE,PARENT INTEGER REFERENCES PT(ID),SEGMENT TEXT,DESCRIPTION TEXT,POSITION INTEGER NOT NULL DEFAULT 0,ARCHIVED INTEGER NOT NULL DEFAULT 0 CHECK(ARCHIVED IN(0,1)),CREATED_AT TEXT,UPDATED_AT TEXT);
CREATE TABLE DOC_TYPE(ID INTEGER PRIMARY KEY AUTOINCREMENT,TYPE TEXT NOT NULL,DESCRIPTION TEXT);
INSERT INTO DOC_TYPE VALUES(1,'SP','Specification document'),(2,'ICD','Interface Control Document');
CREATE TABLE DOCUMENT(ID INTEGER PRIMARY KEY AUTOINCREMENT,PT_ID INTEGER NOT NULL REFERENCES PT(ID),TYPE INTEGER NOT NULL REFERENCES DOC_TYPE(ID),TITLE TEXT NOT NULL UNIQUE,DESCRIPTION TEXT,TEMPLATE_PATH TEXT,METADATA_JSON TEXT);
CREATE TABLE DOCUMENT_REFERENCE(ID INTEGER PRIMARY KEY AUTOINCREMENT,DOC_ID INTEGER NOT NULL REFERENCES DOCUMENT(ID) ON DELETE CASCADE,REFERENCE TEXT NOT NULL,IS_PRIMARY INTEGER NOT NULL DEFAULT 0 CHECK(IS_PRIMARY IN(0,1)),UNIQUE(DOC_ID,REFERENCE));
CREATE UNIQUE INDEX IDX_DOCUMENT_PRIMARY_REFERENCE ON DOCUMENT_REFERENCE(DOC_ID) WHERE IS_PRIMARY=1;
CREATE TABLE REQ_TYPE(ID INTEGER PRIMARY KEY AUTOINCREMENT,TYPE TEXT NOT NULL UNIQUE,CODE TEXT);
INSERT INTO REQ_TYPE(ID,TYPE) VALUES(1,'Informational'),(2,'Feature'),(3,'Use Case'),(4,'User Interface'),(5,'Non Functional'),(6,'Constraint'),(7,'System Function');
CREATE TABLE REQ_STATUS(ID INTEGER PRIMARY KEY AUTOINCREMENT,SHORTCUT TEXT NOT NULL UNIQUE,STATUS TEXT NOT NULL UNIQUE);
INSERT INTO REQ_STATUS VALUES(1,'D','Draft'),(2,'R','Review'),(3,'W','Rework'),(4,'F','Finish'),(5,'I','Implemented'),(6,'V','Valid'),(7,'N','Non Testable'),(8,'O','Obsolete');
CREATE TABLE REQ_METHOD(ID INTEGER PRIMARY KEY AUTOINCREMENT,METHOD TEXT NOT NULL);
INSERT INTO REQ_METHOD VALUES(1,'Analysis'),(2,'Test'),(3,'Review of design');
CREATE TABLE REQUIREMENT(ID INTEGER PRIMARY KEY AUTOINCREMENT,CODE TEXT NOT NULL,TITLE TEXT NOT NULL,DESCRIPTION TEXT,TYPE INTEGER NOT NULL REFERENCES REQ_TYPE(ID),STATUS INTEGER NOT NULL REFERENCES REQ_STATUS(ID),SOURCE TEXT,IS_TRACE_ROOT INTEGER NOT NULL DEFAULT 0 CHECK(IS_TRACE_ROOT IN(0,1)),COMMENTS TEXT);
CREATE UNIQUE INDEX idx_code ON REQUIREMENT(CODE COLLATE NOCASE);
CREATE TABLE REQ_IMAGE(ID INTEGER PRIMARY KEY AUTOINCREMENT,REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,TOKEN TEXT NOT NULL UNIQUE,MIME_TYPE TEXT NOT NULL,LEGEND TEXT,IMAGE BLOB NOT NULL);
CREATE TABLE REQUIREMENT_PT(REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,PT_ID INTEGER NOT NULL REFERENCES PT(ID) ON DELETE CASCADE,IS_PRIMARY INTEGER NOT NULL DEFAULT 0 CHECK(IS_PRIMARY IN(0,1)),PRIMARY KEY(REQ_ID,PT_ID));
CREATE UNIQUE INDEX IDX_REQ_PT_PRIMARY ON REQUIREMENT_PT(REQ_ID) WHERE IS_PRIMARY=1;
CREATE TABLE REQUIREMENT_CODE_SEQUENCE(PT_ID INTEGER PRIMARY KEY REFERENCES PT(ID) ON DELETE CASCADE,NEXT_VALUE INTEGER NOT NULL DEFAULT 1 CHECK(NEXT_VALUE>0));
CREATE TABLE REQUIREMENT_RELATION_TYPE(ID INTEGER PRIMARY KEY,CODE TEXT NOT NULL UNIQUE,LABEL TEXT NOT NULL);
INSERT INTO REQUIREMENT_RELATION_TYPE VALUES(1,'DECOMPOSE','Décompose'),(2,'DERIVES_FROM','Dérive de'),(3,'DEPENDS_ON','Dépend de');
CREATE TABLE REQUIREMENT_RELATION(ID INTEGER PRIMARY KEY AUTOINCREMENT,SOURCE_REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,TARGET_REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,TYPE_ID INTEGER NOT NULL REFERENCES REQUIREMENT_RELATION_TYPE(ID),CREATED_AT TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,COMMENT TEXT,UNIQUE(SOURCE_REQ_ID,TARGET_REQ_ID,TYPE_ID),CHECK(SOURCE_REQ_ID<>TARGET_REQ_ID));
CREATE TABLE REQUIREMENT_VERIFICATION(ID INTEGER PRIMARY KEY AUTOINCREMENT,REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,METHOD_ID INTEGER NOT NULL REFERENCES REQ_METHOD(ID),VERIF_LEVEL TEXT,PROCEDURE_REF TEXT,REDMINE_REF TEXT,MEANS TEXT,VERDICT TEXT CHECK(VERDICT IS NULL OR VERDICT IN('C','PC','NC')),COMMENT TEXT,POSITION INTEGER NOT NULL DEFAULT 0,VERIFICATION_LEVEL_PT_ID INTEGER REFERENCES PT(ID),UNIQUE(REQ_ID,METHOD_ID));
CREATE TABLE REQIF_IDENTITY(REQ_ID INTEGER PRIMARY KEY REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,EXTERNAL_ID TEXT NOT NULL UNIQUE,SOURCE_DOCUMENT TEXT,LAST_SYNC_AT TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE REQIF_ATTRIBUTE(REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,ATTRIBUTE_ID TEXT NOT NULL,ATTRIBUTE_NAME TEXT NOT NULL,VALUE TEXT,VALUE_TYPE TEXT,PRIMARY KEY(REQ_ID,ATTRIBUTE_ID));
CREATE TABLE CONFIGURATION(ID INTEGER PRIMARY KEY AUTOINCREMENT,CODE TEXT NOT NULL UNIQUE,LABEL TEXT NOT NULL,DESCRIPTION TEXT,ACTIVE INTEGER NOT NULL DEFAULT 1 CHECK(ACTIVE IN(0,1)),POSITION INTEGER NOT NULL DEFAULT 0,CREATED_AT TEXT,UPDATED_AT TEXT);
INSERT INTO CONFIGURATION(CODE,LABEL,POSITION) VALUES('PROTO','PROTO',10),('EM','EM',20),('STM','STM',30),('QM','QM',40),('FM','FM',50);
CREATE TABLE PART(ID INTEGER PRIMARY KEY AUTOINCREMENT,PT_ID INTEGER NOT NULL REFERENCES PT(ID),NAME TEXT NOT NULL UNIQUE,SERIAL INTEGER NOT NULL UNIQUE,CONFIG_ID INTEGER NOT NULL REFERENCES CONFIGURATION(ID),DESCRIPTION TEXT);
CREATE TABLE REQUIREMENT_APPLICABILITY(REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,CONFIG_ID INTEGER NOT NULL REFERENCES CONFIGURATION(ID) ON DELETE CASCADE,PT_ID INTEGER REFERENCES PT(ID) ON DELETE CASCADE,APPLICABLE INTEGER NOT NULL DEFAULT 1 CHECK(APPLICABLE IN(0,1)),COMMENT TEXT,PRIMARY KEY(REQ_ID,CONFIG_ID,PT_ID));
CREATE TABLE DOCUMENT_NODE(ID INTEGER PRIMARY KEY AUTOINCREMENT,DOC_ID INTEGER NOT NULL REFERENCES DOCUMENT(ID) ON DELETE CASCADE,PARENT_ID INTEGER REFERENCES DOCUMENT_NODE(ID) ON DELETE CASCADE,NODE_TYPE TEXT NOT NULL CHECK(NODE_TYPE IN('CHAPTER','REQUIREMENT','TEXT','IMAGE')),POSITION INTEGER NOT NULL DEFAULT 0,TITLE TEXT,REQ_ID INTEGER REFERENCES REQUIREMENT(ID),TEXT_CONTENT TEXT,IMAGE_DATA BLOB,IMAGE_LEGEND TEXT,UNIQUE(DOC_ID,PARENT_ID,POSITION));
CREATE TABLE DOCUMENT_EXPORT(ID INTEGER PRIMARY KEY AUTOINCREMENT,DOC_ID INTEGER NOT NULL REFERENCES DOCUMENT(ID),EXPORT_KIND TEXT NOT NULL CHECK(EXPORT_KIND IN('DRAFT','PUBLICATION')),VERSION TEXT,TITLE TEXT,AUTHOR TEXT,EXPORTED_AT TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FILE_PATH TEXT,FILE_SHA256 TEXT,GED_REFERENCE TEXT,GED_LINK TEXT,SNAPSHOT_JSON TEXT,TEMPLATE_PATH TEXT,TEMPLATE_SHA256 TEXT,METADATA_JSON TEXT,DRAFT_LABEL TEXT);
CREATE TABLE INTERFACE(ID INTEGER PRIMARY KEY AUTOINCREMENT,ELEMENT1 INTEGER NOT NULL REFERENCES PT(ID),ELEMENT2 INTEGER NOT NULL REFERENCES PT(ID),DESCRIPTION TEXT,CODE TEXT,STATUS TEXT NOT NULL DEFAULT 'DRAFT',ARCHIVED INTEGER NOT NULL DEFAULT 0 CHECK(ARCHIVED IN(0,1)),CREATED_AT TEXT,UPDATED_AT TEXT);
CREATE TABLE IF_IMAGE(ID INTEGER PRIMARY KEY AUTOINCREMENT,IF_ID INTEGER NOT NULL REFERENCES INTERFACE(ID),LEGEND TEXT,IMAGE BLOB NOT NULL);
CREATE TABLE INTERFACE_TYPE(ID INTEGER PRIMARY KEY AUTOINCREMENT,CODE TEXT NOT NULL UNIQUE,LABEL TEXT NOT NULL);
INSERT INTO INTERFACE_TYPE(CODE,LABEL) VALUES('MECHANICAL','Mécanique'),('ELECTRICAL','Électrique'),('COMMUNICATION','Communication / données'),('THERMAL','Thermique'),('FLUID','Fluide'),('OTHER','Autre');
CREATE TABLE INTERFACE_TYPE_LINK(INTERFACE_ID INTEGER NOT NULL REFERENCES INTERFACE(ID) ON DELETE CASCADE,TYPE_ID INTEGER NOT NULL REFERENCES INTERFACE_TYPE(ID),PRIMARY KEY(INTERFACE_ID,TYPE_ID));
CREATE TABLE INTERFACE_DOCUMENT(INTERFACE_ID INTEGER NOT NULL REFERENCES INTERFACE(ID) ON DELETE CASCADE,DOC_ID INTEGER NOT NULL REFERENCES DOCUMENT(ID) ON DELETE CASCADE,CHAPTER_NODE_ID INTEGER REFERENCES DOCUMENT_NODE(ID),PRIMARY KEY(INTERFACE_ID,DOC_ID));
CREATE TABLE INTERFACE_REQUIREMENT(INTERFACE_ID INTEGER NOT NULL REFERENCES INTERFACE(ID) ON DELETE CASCADE,REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,PRIMARY KEY(INTERFACE_ID,REQ_ID));
CREATE TABLE CHANGE_TYPE(ID INTEGER PRIMARY KEY AUTOINCREMENT,CODE TEXT NOT NULL UNIQUE,LABEL TEXT NOT NULL,ACTIVE INTEGER NOT NULL DEFAULT 1 CHECK(ACTIVE IN(0,1)));
INSERT INTO CHANGE_TYPE(CODE,LABEL) VALUES('CHANGE_REQUEST','Demande de changement'),('WAIVER','Waiver / Dérogation'),('DEVIATION','Déviation'),('OTHER','Autre');
CREATE TABLE CHANGE_STATUS(ID INTEGER PRIMARY KEY AUTOINCREMENT,CODE TEXT NOT NULL UNIQUE,LABEL TEXT NOT NULL,IS_FINAL INTEGER NOT NULL DEFAULT 0 CHECK(IS_FINAL IN(0,1)),POSITION INTEGER NOT NULL DEFAULT 0);
INSERT INTO CHANGE_STATUS(CODE,LABEL,IS_FINAL,POSITION) VALUES('OPEN','Ouvert',0,10),('IN_REVIEW','En instruction',0,20),('APPROVED','Approuvé',1,30),('REJECTED','Rejeté',1,40),('CLOSED','Clos',1,50);
CREATE TABLE CHANGE_ITEM(ID INTEGER PRIMARY KEY AUTOINCREMENT,CODE TEXT NOT NULL UNIQUE,TYPE_ID INTEGER NOT NULL REFERENCES CHANGE_TYPE(ID),STATUS_ID INTEGER NOT NULL REFERENCES CHANGE_STATUS(ID),DESCRIPTION TEXT,DECISION TEXT,OPENED_AT TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CLOSED_AT TEXT,EXTERNAL_REFERENCE TEXT,EXTERNAL_LINK TEXT,ARCHIVED INTEGER NOT NULL DEFAULT 0 CHECK(ARCHIVED IN(0,1)),UPDATED_AT TEXT);
CREATE TABLE CHANGE_LINK(ID INTEGER PRIMARY KEY AUTOINCREMENT,CHANGE_ID INTEGER NOT NULL REFERENCES CHANGE_ITEM(ID) ON DELETE CASCADE,OBJECT_TYPE TEXT NOT NULL CHECK(OBJECT_TYPE IN('REQUIREMENT','PT','CONFIGURATION','INTERFACE','DOCUMENT')),OBJECT_ID INTEGER NOT NULL,UNIQUE(CHANGE_ID,OBJECT_TYPE,OBJECT_ID));
CREATE TABLE EVENT_LOG(ID INTEGER PRIMARY KEY AUTOINCREMENT,EVENT_TIME TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,AUTHOR TEXT,EVENT_TYPE TEXT NOT NULL,OBJECT_TYPE TEXT NOT NULL,OBJECT_ID INTEGER,BEFORE_JSON TEXT,AFTER_JSON TEXT,COMMENT TEXT,EVENT_GROUP TEXT);
CREATE TABLE EVENT_CONTEXT(ID INTEGER PRIMARY KEY CHECK(ID=1),AUTHOR TEXT NOT NULL DEFAULT 'Utilisateur',EVENT_GROUP TEXT);
INSERT INTO EVENT_CONTEXT(ID,AUTHOR) VALUES(1,'Utilisateur');
CREATE TABLE MIGRATION_REPORT(ID INTEGER PRIMARY KEY AUTOINCREMENT,RUN_AT TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FROM_VERSION INTEGER NOT NULL,TO_VERSION INTEGER NOT NULL,REPORT TEXT NOT NULL);
PRAGMA user_version=18;
COMMIT;
PRAGMA foreign_keys=ON;
